def f(n):
    stats = {"calls": 0, "splits": 0, "direct": 0}
    m = (n - 1) // 2
    def h(l, r):
        stats["calls"] += 1
        if l > r:
            return 0
        if r <= m:
            stats["direct"] += 1
            return r - l + 1
        if l > m:
            return 0
        stats["splits"] += 1
        mid = (l + r) // 2
        left = h(l, mid)
        right = h(mid + 1, r)
        return left + right
    res = h(1, n - 1)
    return res, stats

