def f(n, m, k):
    stats = {'loop_iterations': 0, 'segment_completions': 0}
    if k == 1:
        return n*m, stats
    def g(x):
        a, b = 1, 0
        for y in range(1, x+1):
            stats['loop_iterations'] += 1
            new_b = b
            if y >= k:
                stats['segment_completions'] += 1
                new_b += a
            b = new_b
        return b
    val = n * g(m) + m * g(n)
    return val, stats

