def f(L):
    mp = {}
    d = {'find_calls': 0, 'path_updates': 0}
    def fn(u):
        d['find_calls'] += 1
        if u not in mp:
            mp[u] = u
            return u
        root = u
        while mp[root] != root:
            root = mp[root]
        current = u
        while mp[current] != current:
            nxt = mp[current]
            mp[current] = root
            d['path_updates'] += 1
            current = nxt
        return root
    arr = []
    for x, y in L:
        m = ((x + y - 1) // y) * y
        val = fn(m)
        arr.append(val)
        mp[val] = fn(val + y)
    return arr, d

