def f(L):
    from collections import defaultdict
    n = len(L)
    mp = defaultdict(int)
    pair_iterations = 0
    for i in range(n):
        x, y = L[i]
        for j in range(i+1, n):
            u, v = L[j]
            mp[(x+u, y+v)] += 1
            pair_iterations += 1
    active_midpoints = 0
    val = 0
    for cnt in mp.values():
        if cnt > 1:
            active_midpoints += 1
        val += cnt * (cnt - 1) // 2
    return val, {"pair_iterations": pair_iterations, "active_midpoints": active_midpoints}

