def f(n, m, matrix1, matrix2):
    A = [0] * m
    B = [0] * m
    collisions = 0
    updates = 0
    for j in range(m):
        for i in range(n):
            if matrix1[i][j] == '#':
                A[j] |= 1 << i
            if matrix2[i][j] == '#':
                B[j] |= 1 << i
    val = n
    for j in range(m):
        x = A[j]
        y = B[j]
        if x and y:
            collisions += 1
            u = x.bit_length() - 1
            v = (y & -y).bit_length() - 1
            d = v - u - 1
            if d < val:
                val = d
                updates += 1
    return val, {"collisions": collisions, "updates": updates}

