def f(L):
    from collections import Counter
    d = Counter(L)
    mex1_steps = 0
    x = 0
    while d.get(x, 0) >= 1:
        x += 1
        mex1_steps += 1
    m = x
    mex2_steps = 0
    x = 0
    while d.get(x, 0) >= 2:
        x += 1
        mex2_steps += 1
    n = x
    s = m + n
    cache = {}
    lst = [1] * len(L)
    sec_assigns = 0
    for i, val in enumerate(L):
        c = cache.get(val, 0)
        if c < 2:
            lst[i] = c + 1
            cache[val] = c + 1
            if c == 1:
                sec_assigns += 1
        else:
            lst[i] = 1
    return (s, lst), {'mex1_steps': mex1_steps, 'mex2_steps': mex2_steps, 'sec_assigns': sec_assigns}

