    n = len(str1)
    inf_val = float('inf')
    A = [0, inf_val]
    stats = {'transitions': 0, 'penalty_events': 0}
    for i in range(n):
        B = [inf_val, inf_val]
        for x in (0, 1):
            val = A[x]
            if val == inf_val:
                continue
            if i > 0:
                c1 = str2[i-1] if x else str1[i-1]
                c2 = str1[i-1] if x else str2[i-1]
            for y in (0, 1):
                stats['transitions'] += 1
                d1 = str2[i] if y else str1[i]
                d2 = str1[i] if y else str2[i]
                val2 = val
                if i > 0:
                    if c1 == d1:
                        val2 += 1
                        stats['penalty_events'] += 1
                    if c2 == d2:
                        val2 += 1
                        stats['penalty_events'] += 1
                if val2 < B[y]:
                    B[y] = val2
        A = B
    result = A[0] if A[0] < A[1] else A[1]
    return result, stats

