def f(arr):
    n = len(arr)
    pop_ops = 0
    max_updates = 0
    if n < 2:
        return 0, {'pop_ops': pop_ops, 'max_updates': max_updates}
    val = 0
    lst = []
    for i in range(n):
        while lst and arr[lst[-1]] < arr[i]:
            lst.pop()
            pop_ops += 1
        if lst:
            cur = i - lst[-1] - 1
            if cur > val:
                val = cur
                max_updates += 1
        lst.append(i)
    lst.clear()
    for i in range(n - 1, -1, -1):
        while lst and arr[lst[-1]] < arr[i]:
            lst.pop()
            pop_ops += 1
        if lst:
            cur = lst[-1] - i - 1
            if cur > val:
                val = cur
                max_updates += 1
        lst.append(i)
    return val, {'pop_ops': pop_ops, 'max_updates': max_updates}

