def f(n, A, Q):
    U = sorted(set(A))
    m = len(U)
    d = {val:i+1 for i,val in enumerate(U)}
    mx = (n*(m.bit_length()+2))+5
    B = [0]*mx
    C = [0]*mx
    S = [0]*mx
    roots = [0]*(n+1)
    sz = 0
    u_calls = 0
    q_calls = 0

    def update(p, l_, r_, v):
        nonlocal sz, u_calls
        u_calls += 1
        sz += 1
        cur = sz
        B[cur] = B[p]
        C[cur] = C[p]
        S[cur] = S[p] + 1
        if l_ < r_:
            mid = (l_ + r_) // 2
            if v <= mid:
                B[cur] = update(B[p], l_, mid, v)
            else:
                C[cur] = update(C[p], mid+1, r_, v)
        return cur

    def query(p, q, l_, r_, k):
        nonlocal q_calls
        q_calls += 1
        if l_ == r_:
            return l_
        mid = (l_ + r_) // 2
        cnt = S[B[q]] - S[B[p]]
        if k <= cnt:
            return query(B[p], B[q], l_, mid, k)
        else:
            return query(C[p], C[q], mid+1, r_, k-cnt)

    res = []
    for i in range(1, n+1):
        roots[i] = update(roots[i-1], 1, m, d[A[i-1]])
    for a, b, c in Q:
        idx = query(roots[a-1], roots[b], 1, m, c)
        res.append(U[idx-1])
    return res, {'update_calls':u_calls, 'query_calls':q_calls}

