def f(n, A, L):
    from collections import deque
    M = [[] for _ in range(n)]
    for i in range(n):
        for j in L[i]:
            M[j-1].append(i)
    B = [0]*n
    dq = deque()
    u = v = w = 0
    for i in range(n):
        if B[i] == A[i]:
            dq.append(i)
            w += 1
    C = [0]*n
    m = 1
    while dq:
        i = dq.popleft()
        if C[i] != 0 or B[i] != A[i]:
            continue
        C[i] = m
        u += 1
        m += 1
        for j in M[i]:
            B[j] += 1
            v += 1
            if B[j] == A[j]:
                dq.append(j)
                w += 1
    if m <= n:
        out = [-1]
    else:
        out = C
    stats = {"label_assignments": u, "count_increments": v, "enqueue_ops": w}
    return out, stats

