    A = [0, val]
    for x in range(1, n):
        B = [val, val]
        str1 = s[x-1]
        str2 = s[x]
        if str1 == '1' and str2 == '0':
            m += 1
            for y in range(2):
                B[y] = A[y] + 1
        elif str1 == '0' and str2 == '1':
            k += 1
