    arr = list(A)
    if m == 0 or not ops:
        d = {'relevant_ops': 0, 'prefix_size': 0, 'assignments': 0}
        return arr, d
    rel = []
    maxr = 0
    for i in range(m - 1, -1, -1):
        r, t = ops[i]
        if r > maxr:
            maxr = r
            rel.append((r, t))
    k = len(rel)
    if maxr == 0:
        d = {'relevant_ops': k, 'prefix_size': 0, 'assignments': 0}
        return arr, d
    rel.reverse()
    pre = A[:maxr]
    pre.sort()
    left, right = 0, maxr - 1
    x = 0
    for idx, (r, t) in enumerate(rel):
        next_r = rel[idx + 1][0] if idx + 1 < k else 0
        if t == 1:
            for pos in range(r - 1, next_r - 1, -1):
                arr[pos] = pre[right]
                right -= 1
                x += 1
        else:
            for pos in range(r - 1, next_r - 1, -1):
                arr[pos] = pre[left]
                left += 1
                x += 1
    d = {'relevant_ops': k, 'prefix_size': maxr, 'assignments': x}
    return arr, d

