def f(L):
    stats = {'dp_states': 0, 'dfs_calls': 0, 'row_tilings': 0}
    n = len(L)
    if n == 0:
        return (0, stats)
    m = len(L[0])
    arr = []
    for s in L:
        y = 0
        for x, c in enumerate(s):
            if c == '#':
                y |= 1 << x
        arr.append(y)
    d = {0: 1}
    for i in range(n):
        d2 = {}
        for x, val in d.items():
            stats['dp_states'] += 1
            y = x | arr[i]
            def dfs(p, c1, c2):
                stats['dfs_calls'] += 1
                if p == m:
                    d2[c2] = d2.get(c2, 0) + val
                    stats['row_tilings'] += 1
                    return
                if c1 & (1 << p):
                    dfs(p + 1, c1, c2)
                else:
                    dfs(p + 1, c1 | (1 << p), c2 | (1 << p))
                    if p + 1 < m and not (c1 & (1 << (p + 1))):
                        dfs(p + 2, c1 | (1 << p) | (1 << (p + 1)), c2)
            dfs(0, y, 0)
        d = d2
    res = d.get(0, 0)
    return (res, stats)

