def f(n, lst, m):
    import sys
    sys.setrecursionlimit(10**7)
    A = [[] for _ in range(n+1)]
    for x0, y0, val0 in lst:
        A[x0].append((y0, val0))
        A[y0].append((x0, val0))
    mp = {'bs_steps': 0, 'dfs_calls': 0, 'max_cuts': 0}
    def can_do(val):
        c = 0
        def dfs(u, p):
            nonlocal c
            mp['dfs_calls'] += 1
            L = []
            for v0, val1 in A[u]:
                if v0 == p:
                    continue
                up = dfs(v0, u) + val1
                if up > val:
                    c += 1
                else:
                    L.append(up)
            if not L:
                return 0
            L.sort()
            while len(L) > 1 and L[-1] + L[-2] > val:
                c += 1
                L.pop()
            return L[-1]
        x = dfs(1, -1)
        if x > val:
            c += 1
        if c > mp['max_cuts']:
            mp['max_cuts'] = c
        return c <= m
    x = 0
    y = sum(val0 for _, _, val0 in lst) * 2
    while x < y:
        mp['bs_steps'] += 1
        val = (x + y) // 2
        if can_do(val):
            y = val
        else:
            x = val + 1
    return x, mp

