def f(A, B, C):
    A = sorted(A, reverse=True)
    B = sorted(B, reverse=True)
    C = sorted(C, reverse=True)
    n = len(A)
    m = len(B)
    stats = {"rg_ops": 0, "rb_ops": 0, "gb_ops": 0}
    dp_prev = [[0] * (m + 1) for _ in range(n + 1)]
    for x in C:
        dp_curr = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            for j in range(m + 1):
                best = 0
                if i > 0 and j > 0:
                    stats["rg_ops"] += 1
                    v1 = dp_curr[i-1][j-1] + A[i-1] * B[j-1]
                    if v1 > best:
                        best = v1
                if i > 0:
                    stats["rb_ops"] += 1
                    v2 = dp_prev[i-1][j] + A[i-1] * x
                    if v2 > best:
                        best = v2
                if j > 0:
                    stats["gb_ops"] += 1
                    v3 = dp_prev[i][j-1] + B[j-1] * x
                    if v3 > best:
                        best = v3
                dp_curr[i][j] = best
        dp_prev = dp_curr
    return dp_prev[n][m], stats

