def f(n, m, A):
    div_ops = 0
    dp_updates = 0
    pair_evals = 0
    lst = []
    for val in A:
        x = (val & -val).bit_length() - 1
        if x > m:
            x = m
        y = 0
        val2 = val
        while val2 % 5 == 0:
            div_ops += 1
            val2 //= 5
            y += 1
            if y > m:
                y = m
                break
        lst.append((x, y))
    sz = m + 1
    M = [[0] * sz for _ in range(sz)]
    for x, y in lst:
        M[x][y] += 1
    grid = [[0] * (sz + 1) for _ in range(sz + 1)]
    for i in range(sz - 1, -1, -1):
        for j in range(sz - 1, -1, -1):
            grid[i][j] = M[i][j] + grid[i + 1][j] + grid[i][j + 1] - grid[i + 1][j + 1]
            dp_updates += 1
    res = 0
    for i in range(sz):
        for j in range(sz):
            pair_evals += 1
            cnt = M[i][j]
            if cnt == 0:
                continue
            ri = m - i
            if ri < 0:
                ri = 0
            rj = m - j
            if rj < 0:
                rj = 0
            total_ge = grid[ri][rj]
            res += cnt * total_ge
            if i >= ri and j >= rj:
                res -= cnt
    return res // 2, {'div_ops': div_ops, 'dp_updates': dp_updates, 'pair_evals': pair_evals}

