def f(n, A, B):
    L = [[] for _ in range(n+1)]
    for x, y in A:
        L[x].append(y)
    st = [False] * (n+1)
    for x, y in A:
        st[y] = True
    root = next(i for i in range(1, n+1) if not st[i])
    parent = list(range(n+1))
    ancestor = [0] * (n+1)
    vis = [False] * (n+1)
    d = {i: [] for i in range(1, n+1)}
    for idx, (x, y) in enumerate(B):
        d[x].append((y, idx))
        d[y].append((x, idx))
    res = [0] * len(B)
    stats = {"find_calls": 0, "union_calls": 0, "answered_queries": 0}
    def find(u):
        stats["find_calls"] += 1
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]
    def union(u, v):
        stats["union_calls"] += 1
        parent[find(v)] = find(u)
    import sys
    sys.setrecursionlimit(10**7)
    def dfs(u):
        ancestor[find(u)] = u
        for v in L[u]:
            dfs(v)
            union(u, v)
            ancestor[find(u)] = u
        vis[u] = True
        for v, idx in d[u]:
            if vis[v]:
                stats["answered_queries"] += 1
                res[idx] = ancestor[find(v)]
    dfs(root)
    return res, stats

