def f(n, m, val, A):
    d = {'segments': 0, 'compute_calls': 0, 'j_iters': 0}
    if n <= 0:
        return val, d
    A = sorted(A)
    arr = [A[0]]
    for i in range(1, n):
        arr.append(A[i] - A[i-1])
    arr.append(val - A[-1])
    N = len(arr)
    segments = m + 1
    segments = min(segments, N)
    d['segments'] = segments
    if segments >= N:
        return max(arr), d
    prefix = [0] * (N + 1)
    for i in range(1, N+1):
        prefix[i] = prefix[i-1] + arr[i-1]
    prev_dp = prefix[:]
    cur_dp = [float('inf')] * (N + 1)
    def cost(i, j):
        return prefix[j] - prefix[i]
    def compute(k, left, right, optL, optR):
        d['compute_calls'] += 1
        if left > right:
            return
        mid = (left + right) // 2
        best = -1
        cur_dp[mid] = float('inf')
        start = max(optL, k-1)
        end = min(mid-1, optR)
        for j in range(start, end+1):
            d['j_iters'] += 1
            v = max(prev_dp[j], cost(j, mid))
            if v < cur_dp[mid]:
                cur_dp[mid] = v
                best = j
        if best == -1:
            best = start
        compute(k, left, mid-1, optL, best)
        compute(k, mid+1, right, best, optR)
    for k in range(2, segments+1):
        compute(k, k, N, k-1, N-1)
        prev_dp, cur_dp = cur_dp, [float('inf')] * (N + 1)
    return prev_dp[N], d

