def f(n, m, k, A):
    sim_checks = 0
    dp_calls = 0
    mask_checks = 0
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            c = 0
            for t in range(m):
                sim_checks += 1
                if A[i][t] == A[j][t]:
                    c += 1
            M[i][j] = c
            M[j][i] = c
    import functools
    @functools.lru_cache(None)
    def dp(x):
        nonlocal dp_calls
        dp_calls += 1
        y = x.bit_count()
        if y == 0:
            return 0
        if (y & 1) or y > 2 * k:
            return float('-inf')
        i0 = (x & -x).bit_length() - 1
        best = float('-inf')
        z = x ^ (1 << i0)
        while z:
            j0 = (z & -z).bit_length() - 1
            z ^= (1 << j0)
            val = M[i0][j0] + dp(x ^ (1 << i0) ^ (1 << j0))
            if val > best:
                best = val
        return best
    ans = 0
    full = 1 << n
    for x in range(full):
        mask_checks += 1
        if x.bit_count() == 2 * k:
            v = dp(x)
            if v > ans:
                ans = v
    stats = {"char_comparisons": sim_checks, "dp_calls": dp_calls, "masks_tested": mask_checks}
    return ans, stats

