def f(n, str1):
    prefix_ops = 0
    block_scans = 0
    A = [0] * (n + 1)
    for i, c in enumerate(str1):
        A[i + 1] = A[i] + (1 if c == '(' else -1)
        prefix_ops += 1
    if A[n] != 0:
        return (0, 1, 1), {"prefix_ops": prefix_ops, "block_scans": block_scans}
    val = min(A[:n])
    x = A[:n].index(val)
    str2 = str1[x:] + str1[:x]
    B = [0] * (n + 1)
    for i, c in enumerate(str2):
        B[i + 1] = B[i] + (1 if c == '(' else -1)
        prefix_ops += 1
    base = sum(1 for i in range(1, n + 1) if B[i] == 0)
    best = base
    l2, r2 = 1, 1
    C = [i for i in range(n + 1) if B[i] == 0]
    for k in range(len(C) - 1):
        y = C[k]
        m = C[k + 1]
        i = y + 1
        while i < m:
            if B[i] >= 2:
                block_scans += 1
                j = i
                cnt = 0
                while j < m and B[j] >= 2:
                    if B[j] == 2:
                        cnt += 1
                    j += 1
                if base + cnt > best:
                    best = base + cnt
                    l2, r2 = i, j
                i = j
            else:
                i += 1
    if best == base:
        return (base, 1, 1), {"prefix_ops": prefix_ops, "block_scans": block_scans}
    l = ((x + l2 - 1) % n) + 1
    r = ((x + r2 - 1) % n) + 1
    if l > r:
        l, r = r, l
    return (best, l, r), {"prefix_ops": prefix_ops, "block_scans": block_scans}

