def f(n,L):
    stats={'group_ops':0,'unique_colors':0,'partition_calls':0}
    from collections import defaultdict
    import random
    d1=defaultdict(int)
    d2=defaultdict(int)
    for i,val in enumerate(L):
        stats['group_ops']+=1
        if (i+1)%2==0:
            d1[val]+=1
        else:
            d2[val]+=1
    stats['unique_colors']=len(d1)+len(d2)
    arr1=list(d1.items())
    arr2=list(d2.items())
    def quickselect_top_k(arr,k):
        def partition(l,r,pi):
            stats['partition_calls']+=1
            pv=arr[pi][1]
            arr[pi],arr[r]=arr[r],arr[pi]
            si=l
            for x in range(l,r):
                if arr[x][1]>pv:
                    arr[si],arr[x]=arr[x],arr[si]
                    si+=1
            arr[si],arr[r]=arr[r],arr[si]
            return si
        def select(l,r,ks):
            if l==r:
                return
            pi=random.randint(l,r)
            pi=partition(l,r,pi)
            if ks==pi:
                return
            elif ks<pi:
                select(l,pi-1,ks)
            else:
                select(pi+1,r,ks)
        m=len(arr)
        if m<=k:
            top=sorted(arr,key=lambda x:-x[1])
            return top+[(0,0)]*(k-m)
        select(0,m-1,k-1)
        tmp=arr[:k]
        return sorted(tmp,key=lambda x:-x[1])
    t1=quickselect_top_k(arr1,2)
    t2=quickselect_top_k(arr2,2)
    if t1[0][0]!=t2[0][0]:
        mm=t1[0][1]+t2[0][1]
    else:
        v1=t1[0][1]+t2[1][1]
        v2=t1[1][1]+t2[0][1]
        mm=v1 if v1>v2 else v2
    res=n-mm
    return res,stats

