    initial_edges = 0
    artificial_edges = 0
    edge_traversals = 0
    A = [[] for _ in range(n+1)]
    m = len(L)
    for val, (x, y) in enumerate(L, 1):
        initial_edges += 1
        A[x].append((y, val))
        A[y].append((x, val))
    z = m + 1
    for x in range(1, n+1):
        if len(A[x]) % 2:
            artificial_edges += 1
            A[x].append((0, z))
            A[0].append((x, z))
            z += 1
    vis = [False] * z
    B = [None] * (m + 1)
    P = [0] * (n + 1)
    for s in range(n+1):
        if P[s] < len(A[s]):
            stk = [s]
            while stk:
                x = stk[-1]
                while P[x] < len(A[x]) and vis[A[x][P[x]][1]]:
                    P[x] += 1
                if P[x] == len(A[x]):
                    stk.pop()
                else:
                    y, val2 = A[x][P[x]]
                    vis[val2] = True
                    edge_traversals += 1
                    stk.append(y)
                    P[x] += 1
                    if val2 <= m:
                        B[val2] = (x, y)
    return [B[i] for i in range(1, m+1)], {"initial_edges": initial_edges, "artificial_edges": artificial_edges, "edge_traversals": edge_traversals}

