def f(A, k):
    import math
    n = len(A)
    if k < 3 or n < k:
        return 0.0, {'cross_ops': 0, 'dp_ops': 0, 'close_ops': 0}
    B = [math.atan2(y, x) for x, y in A]
    arr = sorted(range(n), key=lambda i: B[i])
    C = [A[i] for i in arr]
    D = C + C
    m = len(D)
    M = [[0] * m for _ in range(m)]
    c1 = c2 = c3 = 0
    for i in range(m):
        x1, y1 = D[i]
        for j in range(i + 1, m):
            x2, y2 = D[j]
            M[i][j] = x1 * y2 - y1 * x2
            c1 += 1
    val_max = 0
    for s in range(n):
        end = s + n
        lst_prev = [float('-inf')] * m
        for j in range(s + 1, end):
            lst_prev[j] = M[s][j]
        for t in range(2, k):
            lst_cur = [float('-inf')] * m
            for j in range(s + 1, end):
                best = float('-inf')
                for l in range(s + 1, j):
                    val = lst_prev[l] + M[l][j]
                    if val > best:
                        best = val
                    c2 += 1
                lst_cur[j] = best
            lst_prev = lst_cur
        idx2 = s + n
        for j in range(s + 1, end):
            val = lst_prev[j] + M[j][idx2]
            if val > val_max:
                val_max = val
            c3 += 1
    return val_max / 2.0, {'cross_ops': c1, 'dp_ops': c2, 'close_ops': c3}

