def f(n, m, M):
    M1 = [[0] * m for _ in range(n)]
    M2 = [[0] * m for _ in range(n)]
    M3 = [[0] * m for _ in range(n)]
    M4 = [[0] * m for _ in range(n)]
    stats = {'dp_updates': 0, 'center_evaluations': 0, 'verify_checks': 0}
    for i in range(n):
        for j in range(m):
            if M[i][j] == '*':
                M1[i][j] = 1 + (M1[i-1][j] if i > 0 else 0)
                stats['dp_updates'] += 1
                M2[i][j] = 1 + (M2[i][j-1] if j > 0 else 0)
                stats['dp_updates'] += 1
    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            if M[i][j] == '*':
                M3[i][j] = 1 + (M3[i+1][j] if i < n-1 else 0)
                stats['dp_updates'] += 1
                M4[i][j] = 1 + (M4[i][j+1] if j < m-1 else 0)
                stats['dp_updates'] += 1
    max_val = 0
    x = -1
    y = -1
    for i in range(n):
        for j in range(m):
            if M[i][j] == '*':
                stats['center_evaluations'] += 1
                cur_val = min(M1[i][j], M3[i][j], M2[i][j], M4[i][j])
                if cur_val > max_val:
                    max_val = cur_val
                    x = i
                    y = j
    if max_val <= 1:
        return 'NO', stats
    B = [[False] * m for _ in range(n)]
    B[x][y] = True
    r = max_val - 1
    for k in range(1, r + 1):
        B[x - k][y] = True
        B[x + k][y] = True
        B[x][y - k] = True
        B[x][y + k] = True
    for i in range(n):
        for j in range(m):
            if M[i][j] == '*':
                stats['verify_checks'] += 1
                if not B[i][j]:
                    return 'NO', stats
    return 'YES', stats

