def f(L):
    union_calls = 0
    find_calls = 0
    connectivity_checks = 0
    res = []
    for A in L:
        if not A:
            res.append(True)
            continue
        mp = {}
        mp2 = {}
        d = {}
        st = set()
        flag = False
        for x, y in A:
            st.add(x)
            st.add(y)
            mp.setdefault(x, x)
            mp.setdefault(y, y)
            mp2.setdefault(x, 0)
            mp2.setdefault(y, 0)
            d.setdefault(x, 0)
            d.setdefault(y, 0)
        def find(a):
            nonlocal find_calls
            find_calls += 1
            if mp[a] != a:
                mp[a] = find(mp[a])
            return mp[a]
        def union(a, b):
            nonlocal union_calls
            union_calls += 1
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return False
            if mp2[ra] < mp2[rb]:
                mp[ra] = rb
            else:
                mp[rb] = ra
                if mp2[ra] == mp2[rb]:
                    mp2[ra] += 1
            return True
        for x, y in A:
            d[y] += 1
            if d[y] > 1:
                flag = True
                break
            if not union(x, y):
                flag = True
                break
        if not flag:
            root_count = sum(1 for n in st if d[n] == 0)
            if root_count != 1 or len(A) != len(st) - 1:
                flag = True
            else:
                root = find(next(iter(st)))
                for n in st:
                    connectivity_checks += 1
                    if find(n) != root:
                        flag = True
                        break
        res.append(not flag)
    stats = {'union_calls': union_calls, 'find_calls': find_calls, 'connectivity_checks': connectivity_checks}
    return res, stats

