def f(n, m, grid):
    import random
    random.seed(0)
    L = [[i for i, ch in enumerate(row) if ch == '1'] for row in grid]
    res = '0' * m
    v = 0
    thr = (n + 1) // 2
    t = min(n, 15)
    c1 = c2 = c3 = 0
    for _ in range(t):
        x = random.randrange(n)
        P = L[x]
        k = len(P)
        if k <= v:
            continue
        if k > 20:
            continue
        c1 += 1
        mp = {}
        for arr in L:
            val = 0
            st = set(arr)
            for i, y in enumerate(P):
                if y in st:
                    val |= 1 << i
            mp[val] = mp.get(val, 0) + 1
        size = 1 << k
        B = [0] * size
        for val, cnt in mp.items():
            B[val] = cnt
        for i in range(k):
            for s in range(size):
                if not (s & (1 << i)):
                    B[s] += B[s | (1 << i)]
                    c2 += 1
        for s in range(size):
            c3 += 1
            if B[s] >= thr:
                pop = s.bit_count()
                if pop > v:
                    v = pop
                    C = ['0'] * m
                    for i, y in enumerate(P):
                        if (s >> i) & 1:
                            C[y] = '1'
                    res = ''.join(C)
    return res, {'pivots_processed': c1, 'zeta_ops': c2, 'mask_checks': c3}

