def f(n, k, L):
    n = len(L)
    A = [0] * n
    B = [0] * n
    for i, (x, y) in enumerate(L):
        A[i] = x + y
        B[i] = x - y
    edges = []
    for d in range(4):
        tmp = []
        for i in range(n):
            if d % 2 == 0:
                X, Y = A[i], B[i]
            else:
                X, Y = B[i], A[i]
            if d >= 2:
                X = -X
            tmp.append((X, Y, i))
        tmp.sort(key=lambda t: (t[0], t[1]))
        keys = [Y - X for X, Y, _ in tmp]
        uniq = sorted(set(keys))
        mp = {val: idx for idx, val in enumerate(uniq)}
        m_val = len(uniq)
        BIT_val = [-10**18] * (m_val + 1)
        BIT_id = [-1] * (m_val + 1)
        def update(idx, val, pid):
            j = idx + 1
            while j <= m_val:
                if val > BIT_val[j]:
                    BIT_val[j] = val
                    BIT_id[j] = pid
                j += j & -j
        def query(idx):
            j = idx + 1
            best = -10**18
            bid = -1
            while j > 0:
                if BIT_val[j] > best:
                    best = BIT_val[j]
                    bid = BIT_id[j]
                j -= j & -j
            return best, bid
        for X, Y, pid in tmp:
            kkey = mp[Y - X]
            best_sum, best_pid = query(kkey)
            if best_pid != -1:
                w = (X + Y) - best_sum
                edges.append((pid, best_pid, w))
            update(kkey, X + Y, pid)
    candidate_edges = len(edges)
    edges.sort(key=lambda e: e[2])
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        else:
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1
        return True
    mst_weights = []
    edges_examined = 0
    for a, b, w in edges:
        edges_examined += 1
        if union(a, b):
            mst_weights.append(w)
            if len(mst_weights) == n - 1:
                break
    if k >= n:
        result = 0
    else:
        mst_weights.sort()
        idx = len(mst_weights) - k
        result = mst_weights[idx] // 2
    return result, {'candidate_edges': candidate_edges, 'edges_examined': edges_examined}

