def f(n, m, k, arr):
    import heapq
    mp = {i: set() for i in range(1, n+1)}
    A = [0] * (n+1)
    for x, y in arr:
        mp[x].add(y)
        mp[y].add(x)
        A[x] += 1
        A[y] += 1
    B = [False] * (n+1)
    heap = [(A[i], i) for i in range(1, n+1)]
    heapq.heapify(heap)
    order = []
    cnt1 = 0
    cnt2 = 0
    while heap:
        val, x = heapq.heappop(heap)
        if B[x] or val != A[x]:
            continue
        if val >= k:
            break
        lst = [y for y in mp[x] if not B[y]]
        B[x] = True
        order.append((x, val, lst))
        cnt1 += 1
        for y in lst:
            A[y] -= 1
            cnt2 += 1
            heapq.heappush(heap, (A[y], y))
    core = [i for i in range(1, n+1) if not B[i]]
    if len(core) >= k:
        result = (1, core)
    else:
        result = None
    cnt3 = 0
    if result is None:
        for x, val, lst in order:
            if val == k - 1:
                cand = [x] + lst
                if len(cand) < k:
                    continue
                clique = cand[:k]
                ok = True
                for i in range(k):
                    for j in range(i+1, k):
                        cnt3 += 1
                        if clique[j] not in mp[clique[i]]:
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    result = (2, clique)
                    break
    if result is None:
        result = (-1, [])
    return result, {"peel_ops": cnt1, "deg_updates": cnt2, "clique_checks": cnt3}

