def f(n, lst):
    from collections import deque, defaultdict
    mp = defaultdict(list)
    mp2 = defaultdict(list)
    for x, y, val in lst:
        mp[x].append((y, val))
        mp2[y].append(x)
    A = [None] * (n + 1)
    q = deque()
    A[n] = 0
    q.append(n)
    c1 = c2 = c3 = 0
    while q:
        x = q.popleft()
        for y in mp2[x]:
            c1 += 1
            if A[y] is None:
                A[y] = A[x] + 1
                q.append(y)
    if A[1] is None:
        return ('', []), {'phase1_edge_checks': c1, 'phase2_edge_checks': c2, 'path_backtrack_steps': c3}
    st = {1}
    visited = {1}
    mp_p = {1: None}
    B = []
    for _ in range(A[1]):
        min_val = 10
        for x in st:
            for y, val in mp[x]:
                c2 += 1
                if A[y] == A[x] - 1 and val < min_val:
                    min_val = val
        B.append(str(min_val))
        st2 = set()
        mp_new = {}
        for x in st:
            for y, val in mp[x]:
                c2 += 1
                if y not in visited and A[y] == A[x] - 1 and val == min_val:
                    visited.add(y)
                    st2.add(y)
                    if y not in mp_p:
                        mp_new[y] = x
        mp_p.update(mp_new)
        st = st2
    lst3 = []
    x = n
    while x is not None:
        c3 += 1
        lst3.append(x)
        x = mp_p.get(x)
    lst3.reverse()
    s = ''.join(B)
    return (s, lst3), {'phase1_edge_checks': c1, 'phase2_edge_checks': c2, 'path_backtrack_steps': c3}

