def f(str1: str, x: int):
    n = len(str1)
    N = 2 * n
    A = [[] for _ in range(N)]
    B = [[] for _ in range(N)]
    imp_count = 0
    dfs1_roots = 0
    scc_count = 0
    def add_imp(u: int, v: int):
        nonlocal imp_count
        imp_count += 1
        A[u].append(v)
        B[v].append(u)
    def var_node(idx: int, val: bool) -> int:
        return 2 * idx + (1 if val else 0)
    def add_or(a_idx: int, a_val: bool, b_idx: int, b_val: bool):
        add_imp(var_node(a_idx, not a_val), var_node(b_idx, b_val))
        add_imp(var_node(b_idx, not b_val), var_node(a_idx, a_val))
