def f(n, A):
    fill_attempts = 0
    dp_checks = 0
    P = []
    for s in A:
        L = len(s)
        mp = {}
        for i in range(1, L):
            if s[i] != '?' and s[i-1] != '?' and s[i] == s[i-1]:
                mp = {}
                break
        if mp is None or (L >= 2 and len(mp) == 0 and any(s[j] != '?' and s[j-1] != '?' and s[j] == s[j-1] for j in range(1, L))):
            mp = {}
        if len(mp) == 0 and not any(s[j] != '?' and s[j-1] != '?' and s[j] == s[j-1] for j in range(1, L)):
            cand0 = ['a','b'] if s[0] == '?' else [s[0]]
            cand1 = ['a','b'] if s[-1] == '?' else [s[-1]]
            for x in cand0:
                for y in cand1:
                    fill_attempts += 1
                    B = list(s)
                    B[0] = x
                    ok = True
                    for j in range(1, L):
                        if B[j] == '?':
                            B[j] = 'a' if B[j-1] == 'b' else 'b'
                        if B[j] == B[j-1]:
                            ok = False
                            break
                    if ok and B[-1] == y:
                        mp[(x, y)] = ''.join(B)
        P.append(mp)
        if not mp:
            return (False, []), {'fill_attempts': fill_attempts, 'dp_checks': dp_checks}
    dp = [{} for _ in range(n)]
    for (x, y), str1 in P[0].items():
