def f(n, arr, lst):
    import sys
    sys.setrecursionlimit(10**7)
    import heapq
    from collections import deque
    INF=10**18
    A=[[] for _ in range(n+1)]
    for x,y,w in arr:
        A[x].append((y,w))
        A[y].append((x,w))
    arr1=[INF]*(n+1)
    cnt1=0
    heap=[]
    for x in lst:
        arr1[x]=0
        heap.append((0,x))
    heapq.heapify(heap)
    while heap:
        x,y=heapq.heappop(heap)
        if x>arr1[y]:
            continue
        for z,w in A[y]:
            nd=x+w
            if nd< arr1[z]:
                arr1[z]=nd
                heapq.heappush(heap,(nd,z))
                cnt1+=1
    arr2=[INF]*(n+1)
    cnt2=0
    arr2[1]=0
    heap=[(0,1)]
    heapq.heapify(heap)
    while heap:
        x,y=heapq.heappop(heap)
        if x>arr2[y]:
            continue
        for z,w in A[y]:
            nd=x+w
            if nd< arr2[z]:
                arr2[z]=nd
                heapq.heappush(heap,(nd,z))
                cnt2+=1
    if arr1[1]==INF:
        return (-1,{'init_relaxations':cnt1,'base_relaxations':cnt2,'fw_relaxations':0})
    diff=[arr1[i]-arr2[i] if arr2[i]<INF else -INF for i in range(n+1)]
    r=max(diff[2:]) if n>=2 else -1
    if r<0:
        return (-1,{'init_relaxations':cnt1,'base_relaxations':cnt2,'fw_relaxations':0})
    cnt3=0
    def g(val):
        nonlocal cnt3
        B=[INF]*(n+1)
        B[1]=val
        heap2=[(val,1)]
        heapq.heapify(heap2)
        while heap2:
            x,y=heapq.heappop(heap2)
            if x> B[y]:
                continue
            for z,w in A[y]:
                nt=x+w
                if nt<=arr1[z] and nt< B[z]:
                    B[z]=nt
                    heapq.heappush(heap2,(nt,z))
                    cnt3+=1
        bad=[False]*(n+1)
        for i in range(1,n+1):
            if B[i]==INF or i==1:
                bad[i]=True
        q=deque([1])
        visited=[False]*(n+1)
        visited[1]=True
        while q:
            y=q.popleft()
            for z,_ in A[y]:
                if bad[z] and not visited[z]:
                    visited[z]=True
                    q.append(z)
        for x in lst:
            if visited[x]:
                return False
        return True
    lo=0
    hi=r
    while lo<hi:
        mid=(lo+hi+1)//2
        if g(mid):
            lo=mid
        else:
            hi=mid-1
    res=lo if g(lo) else -1
    return (res,{'init_relaxations':cnt1,'base_relaxations':cnt2,'fw_relaxations':cnt3})

